                                      <p className={`text-xs font-bold uppercase ${viewTicketModal.survey.demandMet ? 'text-emerald-600' : 'text-rose-600'}`}>{viewTicketModal.survey.demandMet ? 'Sim' : 'Não'}</p>
                                  </div>
                                  <div>
                                      <p className="text-[8px] font-black uppercase text-slate-400">Problema Resolvido?</p>
                                      <p className={`text-xs font-bold uppercase ${viewTicketModal.survey.problemSolved ? 'text-emerald-600' : 'text-rose-600'}`}>{viewTicketModal.survey.problemSolved ? 'Sim' : 'Não'}</p>
                                  </div>
                                  <div>
                                      <p className="text-[8px] font-black uppercase text-slate-400">Gostou do Chat?</p>
                                      <p className={`text-xs font-bold uppercase ${viewTicketModal.survey.likedChat ? 'text-emerald-600' : 'text-rose-600'}`}>{viewTicketModal.survey.likedChat ? 'Sim' : 'Não'}</p>
                                  </div>
                              </div>
                          </div>
                      )}
                  </div>

                  <div className="flex gap-2 pt-2">
                      <button onClick={() => { setViewTicketModal(null); setActiveTicket(viewTicketModal); setActiveTab('chat'); }} className="flex-1 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 transition-all shadow-lg">Abrir Chat Completo</button>
                  </div>
              </div>
          </div>
      )}

      {/* Move Modal (Kept from original) */}
      {moveModalOpen && fileToMove && (
          <div className="fixed inset-0 z-[4000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-6">
              <div className="bg-white w-full max-w-md rounded-[2rem] p-6 shadow-2xl animate-in zoom-in-95">
                  <h3 className="font-black text-slate-900 uppercase italic mb-4">Mover "{fileToMove.name}" para...</h3>
                  <div className="bg-slate-50 rounded-xl border border-slate-200 p-4 h-60 overflow-y-auto custom-scrollbar mb-4">
                      <div onClick={() => setMoveTargetFolderId('root')} className={`p-3 rounded-lg cursor-pointer flex items-center gap-2 ${moveTargetFolderId === 'root' ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-white text-slate-600'}`}><Home size={16}/> Raiz</div>
                      {fileSystem.filter(f => f.type === 'folder' && f.id !== fileToMove.id).map(f => (
                          <div key={f.id} onClick={() => setMoveTargetFolderId(f.id)} className={`p-3 rounded-lg cursor-pointer flex items-center gap-2 ml-4 ${moveTargetFolderId === f.id ? 'bg-indigo-100 text-indigo-700 font-bold' : 'hover:bg-white text-slate-600'}`}><Folder size={16}/> {f.name}</div>
                      ))}
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setMoveModalOpen(false)} className="flex-1 py-3 bg-slate-100 rounded-xl text-[10px] font-black uppercase text-slate-500">Cancelar</button>
                      <button onClick={handleMoveFile} className="flex-1 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg hover:bg-indigo-700">Confirmar</button>
                  </div>
              </div>
          </div>
      )}

      {auditModalOpen && editingStudent && (
          <div className="fixed inset-0 z-[3000] bg-slate-900/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-4xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
                  <header className="bg-slate-50 px-8 py-5 border-b border-slate-100 flex justify-between items-center shrink-0">
                      <div className="flex items-center gap-3"><div className="p-2 bg-indigo-600 text-white rounded-lg shadow-md"><ShieldCheck size={20}/></div><h2 className="text-lg font-black uppercase italic text-slate-900 leading-none">Auditoria de Prontuário</h2></div>
                      <button onClick={() => setAuditModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
                  </header>
                  <div className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-8">
                       <div className="grid grid-cols-2 gap-6">
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Nome</label><input value={editingStudent.displayName} onChange={e => setEditingStudent({...editingStudent, displayName: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">CPF</label><input value={editingStudent.cpf} onChange={e => setEditingStudent({...editingStudent, cpf: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Email</label><input value={editingStudent.email} disabled className="w-full p-3 bg-slate-100 rounded-xl text-xs font-bold text-slate-500 border border-slate-200 cursor-not-allowed"/></div>
                           <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Telefone</label><input value={editingStudent.telefone} onChange={e => setEditingStudent({...editingStudent, telefone: e.target.value})} className="w-full p-3 bg-slate-50 rounded-xl text-xs font-bold border border-slate-100"/></div>
                       </div>
                       <div className="flex gap-4 pt-4 border-t border-slate-100">
                          <button onClick={() => { if (!editingStudent) return; updateDoc(doc(db, 'users', editingStudent.uid), {...editingStudent, updatedAt: serverTimestamp()}).then(() => { alert('Atualizado.'); setAuditModalOpen(false); setEditingStudent(null); }); }} className="px-6 py-3 bg-slate-100 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-200 flex items-center gap-2"><Edit3 size={14}/> Salvar Edições</button>
                          <button onClick={() => { if (!editingStudent) return; updateDoc(doc(db, 'users', editingStudent.uid), {status: 'ativo', updatedAt: serverTimestamp()}).then(() => { alert('Validado.'); setAuditModalOpen(false); setEditingStudent(null); }); }} className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-700 transition-all flex items-center gap-2 shadow-xl shadow-emerald-200"><Check size={16}/> Validar Matrícula</button>
                       </div>
                  </div>
              </div>
          </div>
      )}
      {isSignModalOpen && <SignaturePad title="Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Assinatura Salva!"); }} />}
    </div>
  );
};

export default SecretariatView;
